    `OpenCount`          int(5) NOT NULL DEFAULT 0,
    `ClickCount`         int(5) NOT NULL DEFAULT 0,
    `TrackerId`          text     NOT NULL,
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `MacantaExportRequest`;
CREATE TABLE `MacantaExportRequest`
(
    `Id`              int(15) NOT NULL AUTO_INCREMENT,
    `UserId`          int(15) NOT NULL,
    `Type`            text     NOT NULL,
    `TypeId`          text     NOT NULL,
    `ContactInfoPath` text              DEFAULT NULL,
    `NotesTaskPath`   text     NOT NULL,
    `DataObjectPath`  text     NOT NULL,
    `Progress`        text     NOT NULL,
    `Status`          enum('Queued','Running','Done') NOT NULL DEFAULT 'Queued',
    `Created`         datetime NOT NULL DEFAULT current_timestamp(),
    `Updated`         datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp (),
    PRIMARY KEY (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `MacantaImportRequest`;
CREATE TABLE `MacantaImportRequest`
(
    `Id`             int(15) NOT NULL AUTO_INCREMENT,
    `UserId`         int(15) NOT NULL,
    `Type`           text     NOT NULL,
    `ConnetedDataId` text              DEFAULT NULL,
    `FileName`       text              DEFAULT NULL,
    `FileSourcePath` text     NOT NULL,
    `Progress`       text     NOT NULL,
    `Status`         enum('Queued','Running','Done') NOT NULL DEFAULT 'Queued',
    `Created`        datetime NOT NULL DEFAULT current_timestamp(),
    `Updated`        datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp (),
    PRIMARY KEY (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `MacantaMeta`;
CREATE TABLE `MacantaMeta`
(
    `Id`        int(30) NOT NULL AUTO_INCREMENT,
    `Key`       text         NOT NULL,
    `Type`      enum('API','Contact','Note','Task','CustomTab','DataObject','ContactObject','DataObjectItem','Automation','Other') NOT NULL DEFAULT 'Other' COMMENT 'Can be  User, Contact, Note or Task, DataObject, DataObjectItem, Automation and Other',
    `Reference` varchar(150) NOT NULL COMMENT 'The Id or Name of Any Type',
    `Data`      longtext     NOT NULL,
    `Status`    varchar(30)           DEFAULT 'active',
    `Created`   datetime     NOT NULL DEFAULT current_timestamp(),
    `Updated`   datetime     NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp (),
    PRIMARY KEY (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `MacantaSMSSent`;
CREATE TABLE `MacantaSMSSent`
(
    `id`         int(10) NOT NULL AUTO_INCREMENT,
    `Message`    longtext NOT NULL,
    `To`         text     NOT NULL,
    `From`       text     NOT NULL,
    `ContactId`  int(10) DEFAULT NULL,
    `UserInfo`   text     DEFAULT NULL,
    `SentDate`   datetime DEFAULT current_timestamp(),
    `SentResult` longtext NOT NULL,
    `Error`      longtext NOT NULL,
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `MacantaStripoEmail`;
CREATE TABLE `MacantaStripoEmail`
(
    `Id`                   int(5) NOT NULL AUTO_INCREMENT,
    `EmailId`              varchar(100) NOT NULL,
    `Title`                text         NOT NULL,
    `Version`              int(5) NOT NULL DEFAULT 1,
    `CompiledEmailHTML`    longtext     NOT NULL,
    `CompiledEmailAmpHTML` longtext     NOT NULL,
    `EmailHTML`            longtext     NOT NULL,
    `EmailCSS`             longtext     NOT NULL,
    `TemplateHTML`         longtext     NOT NULL,
    `TemplateCSS`          longtext     NOT NULL,
    `Screenshot`           longtext     NOT NULL,
    `Global`               enum('yes','no') NOT NULL DEFAULT 'no',
    `TemplateGroupId`      varchar(10)  NOT NULL,
    `Type`                 varchar(30)  NOT NULL DEFAULT 'built-in',
    `Status`               enum('active','disabled') NOT NULL DEFAULT 'disabled',
    `Updated`              datetime     NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp (),
    `Created`              datetime     NOT NULL DEFAULT current_timestamp(),
    PRIMARY KEY (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `MacantaStripoEmailGroup`;
CREATE TABLE `MacantaStripoEmailGroup`
(
    `Id`            int(5) NOT NULL AUTO_INCREMENT,
    `Title`         text     NOT NULL,
    `UserContactId` int(15) NOT NULL,
    `Created`       datetime NOT NULL DEFAULT current_timestamp(),
    `Updated`       datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp (),
    PRIMARY KEY (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `MacantaUpdate`;
CREATE TABLE `MacantaUpdate`
(
    `Id`          int(15) NOT NULL AUTO_INCREMENT,
    `Title`       text        NOT NULL,
    `Version`     varchar(30) NOT NULL,
    `Status`      enum('draft','publish') NOT NULL,
    `PublishDate` datetime    NOT NULL,
    `Content`     longtext    NOT NULL,
    `Meta`        longtext    NOT NULL,
    `Created`     datetime    NOT NULL DEFAULT current_timestamp(),
    `Updated`     datetime    NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp (),
    PRIMARY KEY (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `MacantaUser`;
CREATE TABLE `MacantaUser`
(
    `Id`           int(30) NOT NULL AUTO_INCREMENT,
    `ContactId`    varchar(30) NOT NULL,
    `ContactLevel` varchar(50) NOT NULL,
    `TemplateId`   int(11) NOT NULL,
    `Status`       varchar(50) NOT NULL,
    `Created`      datetime    NOT NULL,
    `Updated`      datetime    NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp (),
    PRIMARY KEY (`Id`),
    KEY            `ContactId` (`ContactId`),
    KEY            `TemplateId` (`TemplateId`),
    CONSTRAINT `MacantaUser_ibfk_1` FOREIGN KEY (`ContactId`) REFERENCES `MacantaContact` (`Id`) ON DELETE CASCADE ON UPDATE NO ACTION,
    CONSTRAINT `MacantaUser_ibfk_2` FOREIGN KEY (`TemplateId`) REFERENCES `MacantaUserPermissionTemplates` (`TemplateId`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `MacantaUserNotification`;
CREATE TABLE `MacantaUserNotification`
(
    `Id`              int(10) NOT NULL AUTO_INCREMENT,
    `ContactFullName` varchar(50) NOT NULL,
    `ContactEmail`    text        NOT NULL,
    `ContactId`       int(11) NOT NULL,
    `UserContactId`   int(11) NOT NULL,
    `Message`         text        NOT NULL,
    `Meta`            text        NOT NULL,
    `Status`          enum('New','Viewed') NOT NULL DEFAULT 'New',
    `Type`            enum('Alert','Relationship','Conversation','Task','API.Onboarding','API.Alert','API.Relationship','API.Task') NOT NULL,
    `Created`         datetime    NOT NULL DEFAULT current_timestamp(),
    PRIMARY KEY (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `MacantaUserPermissionTemplates`;
CREATE TABLE `MacantaUserPermissionTemplates`
(
    `TemplateId`                int(11) NOT NULL AUTO_INCREMENT,
    `TemplateName`              varchar(100) NOT NULL,
    `TemplateDescription`       text         NOT NULL,
    `TabAccess`                 longtext     NOT NULL,
    `SectionAccess`             longtext     NOT NULL,
    `MQBAccess`                 longtext     NOT NULL,
    `PermissionMeta`            longtext     NOT NULL,
    `TaskAccess`                longtext     NOT NULL,
    `InlineEmailTemplateAccess` longtext     NOT NULL,
    `MQBWidgetAccess`           longtext     NOT NULL,
    `MQBWidgetEmail`            longtext     NOT NULL,
    `UserGuides`                longtext     NOT NULL,
    `ContactViewPermissions`    longtext     NOT NULL,
    `WorkflowBoards`            longtext     NOT NULL,
    `Status`                    varchar(30)  NOT NULL,
    `Created`                   datetime     NOT NULL,
    `Updated`                   datetime     NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp (),
    PRIMARY KEY (`TemplateId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `MacantaUserSession`;
CREATE TABLE `MacantaUserSession`
(
    `id`              int(11) NOT NULL AUTO_INCREMENT,
    `user_id`         int(30) NOT NULL,
    `login_email`     text                  DEFAULT NULL,
    `last_access`     int(11) NOT NULL,
    `session_name`    text                  DEFAULT NULL,
    `session_started` int(11) NOT NULL,
    `session_ttl`     int(11) NOT NULL DEFAULT 86400,
    `session_data`    longtext              DEFAULT NULL,
    `recent_actions`  varchar(500) NOT NULL DEFAULT '[]',
    PRIMARY KEY (`id`),
    KEY               `user_id` (`user_id`),
    CONSTRAINT `MacantaUserSession_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `MacantaUser` (`Id`) ON DELETE CASCADE ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8;


DROP TABLE IF EXISTS `MacantaWidgetMessagingQueue`;
CREATE TABLE `MacantaWidgetMessagingQueue`
(
    `id`          int(5) NOT NULL AUTO_INCREMENT,
    `UserId`      int(30) NOT NULL,
    `SessionName` varchar(50) NOT NULL,
    `Type`        varchar(50) NOT NULL DEFAULT 'Email',
    `QueryId`     varchar(50) NOT NULL,
    `Subject`     text        NOT NULL,
    `Message`     longtext    NOT NULL,
    `SenderEmail` text        NOT NULL,
    `SenderName`  text        NOT NULL,
    `GroupName`   varchar(50) NOT NULL,
    `WidgetName`  varchar(50) NOT NULL,
    `Attachments` longtext    NOT NULL,
    `Status`      varchar(50) NOT NULL DEFAULT 'Queued',
    `Progress`    varchar(50) NOT NULL DEFAULT 'Waiting',
    `Created`     datetime    NOT NULL DEFAULT current_timestamp(),
    `Updated`     datetime    NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp (),
    `Runtime`     int(15) DEFAULT NULL,
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `MacantaWidgetMessagingThread`;
CREATE TABLE `MacantaWidgetMessagingThread`
(
    `Id`           int(11) NOT NULL AUTO_INCREMENT,
    `QueueId`      int(5) NOT NULL,
    `ThreadId`     varchar(30) NOT NULL,
    `Limit`        int(5) NOT NULL,
    `Offset`       int(5) NOT NULL,
    `CurrentCount` int(5) NOT NULL,
    `Status`       enum('Processing','Done') NOT NULL DEFAULT 'Processing',
    `Created`      datetime    NOT NULL DEFAULT current_timestamp(),
    `Updated`      datetime    NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp (),
    PRIMARY KEY (`Id`),
    KEY            `QueueId` (`QueueId`),
    CONSTRAINT `MacantaWidgetMessagingThread_ibfk_1` FOREIGN KEY (`QueueId`) REFERENCES `MacantaWidgetMessagingQueue` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `macanta_logs`;
CREATE TABLE `macanta_logs`
(
    `id`      int(9) NOT NULL AUTO_INCREMENT,
    `Name`    text DEFAULT NULL,
    `Message` text DEFAULT NULL,
    `Created` text DEFAULT NULL,
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;


DROP TABLE IF EXISTS `note_tags`;
CREATE TABLE `note_tags`
(
    `id`         int(11) NOT NULL AUTO_INCREMENT,
    `note_id`    varchar(100) DEFAULT NULL,
    `contact_id` varchar(100) DEFAULT NULL,
    `tag_slugs`  varchar(100) DEFAULT NULL,
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `RestHookRequest`;
CREATE TABLE `RestHookRequest`
(
    `id`            int(9) NOT NULL AUTO_INCREMENT,
    `message`       longtext              DEFAULT NULL,
    `date_received` datetime              DEFAULT NULL,
    `status`        varchar(100) NOT NULL DEFAULT 'ready',
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;


DROP TABLE IF EXISTS `rucksack_logs`;
CREATE TABLE `rucksack_logs`
(
    `id`        int(9) NOT NULL AUTO_INCREMENT,
    `UserId`    int(15) NOT NULL,
    `Name`      text DEFAULT NULL,
    `Params`    text DEFAULT NULL,
    `Details`   text DEFAULT NULL,
    `DateTaken` text DEFAULT NULL,
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;


DROP TABLE IF EXISTS `SyncProcess`;
CREATE TABLE `SyncProcess`
(
    `TableName`   varchar(32) NOT NULL,
    `TotalItems`  int(11) NOT NULL,
    `CurrentItem` int(11) NOT NULL,
    `Operation`   varchar(32) NOT NULL,
    `Status`      varchar(32) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `SyncRecord`;
CREATE TABLE `SyncRecord`
(
    `TableName`  text     NOT NULL,
    `LastSynced` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `tags`;
CREATE TABLE `tags`
(
    `id`       int(11) NOT NULL AUTO_INCREMENT,
    `tag_slug` varchar(100) NOT NULL,
    `tag_name` varchar(100) DEFAULT NULL,
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `users_meta`;
CREATE TABLE `users_meta`
(
    `id`         int(11) NOT NULL AUTO_INCREMENT,
    `user_id`    varchar(100) NOT NULL,
    `meta_key`   varchar(100) NOT NULL,
    `meta_value` longtext DEFAULT NULL,
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `user_sessions`;
CREATE TABLE `user_sessions`
(
    `id`              int(11) NOT NULL AUTO_INCREMENT,
    `user_id`         varchar(30) CHARACTER SET utf8mb4 NOT NULL,
    `login_email`     text                                       DEFAULT NULL,
    `last_access`     int(11) NOT NULL,
    `session_name`    text                                       DEFAULT NULL,
    `session_started` int(11) NOT NULL,
    `session_ttl`     int(11) NOT NULL DEFAULT 86400,
    `session_data`    longtext                                   DEFAULT NULL,
    `recent_actions`  varchar(500)                      NOT NULL DEFAULT '[]',
    PRIMARY KEY (`id`),
    KEY               `user_id` (`user_id`),
    CONSTRAINT `user_sessions_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `MacantaUser` (`ContactId`) ON DELETE CASCADE ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8;


